window.GOHUD_SEARCH=window.GOHUD_SEARCH||{};
window.GOHUD_SEARCH["es"]={"p":["index.html","theming.html","widgets.html"],"n":["Introducción","Temas","Widgets"],"d":[[0,"showcase","Cómo se ve dentro de un juego",0,"Los preajustes medieval y de ciencia ficción — hojas de personaje, inventarios y misiones; formularios, cuadrículas y tarjetas de pregunta; paneles angulares y controles táctiles. Cambiar de preajuste es una línea de código. Medieval — personaje, inventario y misiones Medieval — formularios, cuadrículas y tarjetas de pregunta Ciencia ficción — paneles angulares y controles táctiles Los seis preajustes y cómo cambiar entre ellos →","",-1],[0,"what","De qué se encarga por ti",0,"Lo que más tiempo cuesta en la interfaz de un juego no es la forma de un botón: es todo lo que se desajusta de un dispositivo a otro. gohud resuelve ese desajuste en un único lugar. Cada medida es un token Los espaciados, las esquinas y los tamaños de texto se invocan por nombre, no se escriben como números. Cambia el tema y toda la pantalla se mueve con él. Tamaño visible ≠ tamaño pulsable Un botón de cerrar se ve de 36dp, pero su área táctil es de 48dp. Donde se solapan ranuras apretadas, gana la pulsación aquella cuyo centro está más cerca. Muescas y teclados Las piezas del HUD se quedan dentro del área segura, y un campo de entrada sube por encima del teclado virtual cuando este aparece. Atrás cierra una sola cosa Escape y el botón Atrás de Android cierran solo la superficie superior. Las ventanas apiladas no desaparecen todas juntas. Los avisos nunca roban la entrada Pulsa a través de un snackbar y el botón que está debajo la recibe. Tampoco toma el foco. Los iconos se piden por nombre Los widgets solo conocen GoIconSet.CLOSE. Cambia el juego de iconos y todos los dibujos cambian sin tocar una línea de código. Seis aspectos, una línea GoUi.use_preset() cambia a la vez el tema, el skin y los iconos — esquinas redondeadas, ciencia ficción achaflanada o marcos medievales forjados. Legible por medición Todos los temas se verifican contra la WCAG, incluidos los estados de los botones y los paneles de HUD translúcidos sobre blanco puro y negro puro. Todo funciona sin activar el plugin. Activarlo añade un autoload GoRuntime que sigue el tamaño de la ventana, la escala dp y la altura del teclado, además de ajustes de proyecto para el recurso de configuración y el preajuste — comodidades, no requisitos.","",-1],[0,"install","Instalación",0,"Copia la carpeta del add-on dentro de tu proyecto. No hay nada más que configurar.","",-1],[0,"from-the-asset-store-or-a-release-zip","Desde la Asset Store o un ZIP de la versión",1,"Descomprime en la raíz de tu proyecto para obtener res://addons/gohud/. Eso es todo. De forma opcional, activa Proyecto → Ajustes del proyecto → Plugins → gohud.","",2],[0,"as-a-git-submodule","Como submódulo de git",1,"La raíz del repositorio es la carpeta del add-on, así que queda exactamente donde Godot la espera. Edita ahí mismo, haz commit y push dentro de addons/gohud y luego registra el puntero del submódulo en tu juego. Se requiere Godot 4.6 o posterior. gohud usa APIs introducidas en 4.5 (DPITexture, FoldableContainer, propiedades de accesibilidad), así que en versiones anteriores falla al analizar el código. 4.6 es la versión mínima admitida, registrada en GoUi.MIN_ENGINE.","git submodule add https://github.com/thruthesky/gohud.git addons/gohud git submodule update --init git -C addons/gohud checkout v1.0.0 # opcional: fija una etiqueta o un commit",2],[0,"start","Inicio rápido",0,"Todo widget es .new() y add_child() — sin archivos de escena, sin autoload.","",-1],[0,"pick-a-look-before-building-ui-optional","Elige un aspecto antes de construir la interfaz (opcional)",1,"","GoUi.use_preset(GoThemePresets.SCIFI_DARK) # si lo omites se usa default_dark",5],[0,"a-confirmation-you-await","Una confirmación con await",1,"Pasa destructive = true (el último argumento) y el botón de confirmar se dibuja como un botón de peligro relleno.","var dialogs := GoDialogs.new() add_child(dialogs) if await dialogs.confirm(\"Borrar partida\", \"Esto no se puede deshacer.\"): delete_save()",5],[0,"a-bottom-sheet-with-a-sticky-search-field-and-fo","Una hoja inferior con campo de búsqueda y pie fijos",1,"Por qué las filas fijas están separadas del cuerpo desplazable. Si pones confirmar y cancelar en body, una lista larga los empuja fuera de la pantalla. footer() siempre está visible.","var sheet := GoSheet.new() add_child(sheet) sheet.open(\"Inventario\") sheet.toolbar().add_child(GoStyle.line_edit(\"Buscar…\")) sheet.toolbar().visible = true for item in items: sheet.body.add_child(GoStyle.list_button(GoIconSet.BOX, item.name, _use.bind(item), Color.TRANSPARENT, item.description, false)) sheet.footer().add_child(GoStyle.button(\"Cerrar\", sheet.close, GoStyle.Tone.PRIMARY)) sheet.footer().visible = true",5],[0,"a-hud-corner","Una esquina del HUD",1,"","var corner := GoHudAnchor.new() corner.spot = GoHudAnchor.Spot.TOP_LEFT corner.landscape_spot = GoHudAnchor.Spot.TOP_RIGHT add_child(corner) var hp := GoBar.new() hp.label_text = \"HP\" hp.ink = GoUi.color(GoTheme.DANGER_FILL) corner.add_child(hp) hp.set_values(320, 500)",5],[0,"content-that-keeps-clear-of-the-hud","Contenido que se mantiene fuera del HUD",1,"Cada rectángulo se esquiva en la dirección que menos área cuesta — hacia abajo en un teléfono vertical, hacia los lados en horizontal. Cómo el HUD se esquiva a sí mismo →","form.avoid_hud = true # se aparta de todo GoHudAnchor visible joystick_anchor.reserve_space = false # …salvo los que solo aparecen bajo un dedo notice_anchor.avoid_peers = true # el aviso se coloca bajo el HUD fijo en vez de taparlo",5],[0,"presets","Cambia el aspecto — colores y forma",0,"Un Theme solo puede reestilizar lo que dibuja el motor. Las esquinas redondeadas son las únicas que tiene StyleBoxFlat, y el joystick, las ranuras rápidas y la marca guía los dibuja el código — así que un tema por sí solo jamás puede cambiar su forma. Por eso gohud incluye preajustes: un tema, un skin y un juego de iconos elegidos como una sola unidad. Preajuste Aspecto default_dark El gohud original — esquinas redondeadas, acento azul suave default_light Las mismas formas sobre una paleta clara scifi_dark Esquinas achaflanadas, bordes de neón cian y resplandor, joystick hexagonal, corchetes de puntería scifi_light Las mismas formas angulares en una paleta de plano técnico medieval_dark Hierro y cuero oscuros, marcos de oro antiguo, remaches, iconos grabados, títulos en Cinzel medieval_light Pergamino, tinta y bronce con los mismos marcos forjados default_dark — esquinas redondeadas, acento azul suave default_light — mismas formas, paleta clara scifi_dark — esquinas achaflanadas, neón cian scifi_light — mismas formas angulares, paleta de plano técnico Esas cuatro son la misma pantalla de la galería. No cambia ni una línea de código — solo el nombre del preajuste. Las esquinas de los botones, la forma de los interruptores, las filas de lista y los bordes de los campos se mueven juntos.","GoUi.use_preset(GoThemePresets.MEDIEVAL_DARK) # tema, skin e iconos a la vez",-1],[0,"medieval-collection","Colección medieval",1,"medieval_dark combina hierro y cuero con oro antiguo; medieval_light usa pergamino y tinta. Los marcos de menú llevan un remache y un pequeño ornamento en la esquina, mientras que el HUD siempre visible se mantiene discreto; 16 iconos grabados redibujan los nombres de objeto, y solo los títulos y subtítulos usan la fuente Cinzel incluida. medieval_dark — hierro y cuero medieval_light — pergamino y tinta Ambas capturas son examples/medieval/medieval.tscn, construido con los widgets estándar. La guía medieval y cómo crear tu propio reino →","",11],[0,"the-same-screen-on-a-phone-and-on-a-desktop","La misma pantalla en un teléfono y en un escritorio",1,"Las capturas de la galería son un teléfono en vertical. Abajo está el mismo código a 1280×800 — el contenido se detiene en un ancho legible (480dp) y se centra, mientras el HUD se queda en las esquinas. El formulario rodea las piezas flotantes del HUD, pero no se mueve cuando ya está despejado de ellas: empujarlo de todos modos dejaría el contenido descentrado en una pantalla ancha. default_dark · 1280×800 scifi_dark · 1280×800","",11],[0,"the-same-sheet-a-different-look","La misma hoja, otro aspecto",1,"Predeterminado — tarjeta redondeada, fila de búsqueda y pie fijos Ciencia ficción — borde de acento superior, esquinas cortadas, resplandor Elige uno en Ajustes del proyecto → gohud → Theme → Preset, o asigna GoConfig.preset. Rellenar theme, skin o icons de forma explícita tiene prioridad sobre el preajuste, así que puedes tomar un preajuste y sobrescribir solo uno de ellos. Un tema nuevo es un solo archivo JSON. new_theme.py kingdom --from medieval_dark escribe una paleta que detalla cada valor heredado; make_theme.py kingdom genera el tema, sus recursos gráficos de control y los dials de su skin, y el preajuste aparece en el selector. Cada ajuste y cada dial →","",11],[0,"skin","Skins — allí donde un Theme no llega",0,"Un skin gobierna el joystick, las caras de las ranuras rápidas, el anillo de la marca guía, los chips, los esqueletos, las alertas, los separadores y los encabezados de sección. Créale una subclase y sobrescribe solo lo que quieras cambiar. Clase Formas que puede crear GoStyleBoxCut Esquinas cortadas en diagonal (chaflán), un borde de acento engrosado, un resplandor exterior GoStyleBoxBracket Solo marcas en las esquinas, sin encerrar el contenido GoStyleBoxMedieval Un marco forjado con remaches, grabado en las esquinas, un realce biselado y grano de material Las tres se serializan dentro de un recurso Theme — y eso es lo que permite que un tema cambie la forma, no solo el color. GoSkinSciFi y GoSkinMedieval son las subclases incluidas. GoStyle.box() siempre devuelve un StyleBoxFlat, porque el código que lo llama lo recibe y ajusta bg_color o corner_radius. Usa GoStyle.surface() cuando una forma personalizada deba sobrevivir.","class_name MySkin extends GoSkin func slot_box(accent: Color, lit: bool) -> StyleBox: var box := GoStyleBoxCut.new() box.bg_color = accent box.cut = 6.0 box.edge_color = accent return box",-1],[0,"widgets","Widgets",0,"Las piezas, en una sola tabla. Cada una en detalle → Clase Base Qué hace GoSurface Control Contenedor de tarjeta flotante — colocación centrada, inferior o anclada, encabezado y pie fijos, cuerpo desplazable, redimensionado por arrastre GoSheet CanvasLayer Páginas que suben desde abajo, en su propia capa para quedar por encima del HUD GoDialogs Node Confirmaciones y alertas con await; destructive para acciones irreversibles GoForm MarginContainer Formularios de ancho limitado que esquivan el teclado virtual y, con avoid_hud, el HUD GoScroll ScrollContainer Desplazamiento táctil; la barra de desplazamiento se mete en el relleno de la tarjeta GoNotice PanelContainer Un snackbar que no toma ni la entrada ni el foco GoPromptCard PanelContainer Una pregunta que no bloquea el juego GoCoachMark Control Un recorrido guiado que señala controles reales; pulsar el objetivo avanza GoHudAnchor Control Fija piezas del HUD en uno de nueve puntos del área segura GoBar Control Barras de vida, maná y experiencia con cambios suavizados GoSlot Button Una ranura rápida — icono, cantidad, enfriamiento y atajo en una sola cara GoJoystick Control Stick virtual en modo fijo, de seguimiento o relativo GoIconButton Button Se ve pequeño, se pulsa grande GoStyle static Botones, filas de lista, campos, chips, tablas, pestañas y más, creados de una única manera coherente","",-1],[0,"examples","Ejemplos que puedes ejecutar",0,"Tres formas de ver gohud antes de escribir una línea — ninguna necesita servidor ni autoload. Ejemplo Cómo abrirlo Qué muestra Galería examples/gallery/gallery.tscn · F6 Todos los widgets, un selector para cada preajuste instalado y el juego de iconos completo Medieval examples/medieval/medieval.tscn · F6 Una hoja de personaje, un zurrón y un diario de misiones; los botones alternan entre hierro y pergamino y abren el detalle de los objetos App de demo cd examples/demo && godot Una pantalla de inicio que abre la galería, el recorrido guiado de 15 capítulos, la pantalla de muestra y el aspecto medieval, con widgets en vivo y una tarjeta por clase La app de demo no necesita ninguna preparación: si falta el enlace al add-on o la caché de importación, lo indica, repara la carpeta y se vuelve a abrir sola. Su pantalla de inicio abre cada ejemplo dentro de la misma ventana — pulsa 1–4 o haz clic en una fila, y la barra superior te trae de vuelta. En el recorrido, C alterna el modo cine, F11 la pantalla completa, Espacio pausa (o reproduce el widget actual mientras exploras), las flechas cambian de capítulo y Escape vuelve al inicio. ¿Usas un agente de programación con IA? Abre los tres con un solo comando →","cd examples/demo && godot # pantalla de inicio; enlaza e importa en la primera ejecución bash examples/demo/run.sh # la misma app, desde la raíz del add-on bash examples/demo/run.sh -- --open=gallery # omite la pantalla de inicio bash examples/demo/run.sh -- --explore=surfaces # abre directamente en un capítulo del recorrido bash examples/demo/run.sh --record /tmp/gohud-demo.avi # grabación del recorrido a 1080p / 60 fps",-1],[0,"ai","Ábrelo desde tu agente de programación con IA",0,"gohud incluye un plugin de Claude Code con comandos de barra. Escribe uno y la galería o la demo se abre en su propia ventana de Godot — sin arrancar el editor, sin buscar una escena.","",-1],[0,"install-the-commands-once","Instala los comandos una sola vez",1,"Otros agentes como Codex pueden usar la misma skill: copia skills/gohud de este repositorio en la carpeta de skills del agente.","claude plugin marketplace add thruthesky/gohud claude plugin install gohud@gohud # luego reinicia Claude Code",18],[0,"gohud-preview-the-widget-gallery","/gohud:preview — la galería de widgets",1,"Abre la galería: todos los widgets, un selector para los seis preajustes y el juego de iconos completo. Escríbelo dentro de tu proyecto de Godot y usará tu addons/gohud; sin proyecto usa la copia incluida con el plugin, o un clon nuevo. Se ejecuta en un proyecto de prueba desechable, así que tus autoloads y tu caché de importación quedan intactos, y la ventana permanece abierta hasta que la cierras.","",18],[0,"gohud-preview-demo-the-15-chapter-guided-tour","/gohud:preview demo — el recorrido guiado de 15 capítulos",1,"Abre la demo en su pantalla de inicio. Start demo reproduce el recorrido con entrada real; Explore widgets te deja probar un widget a mano. Las teclas listadas en Ejemplos también funcionan aquí.","",18],[0,"many-other-commands","Muchos otros comandos",1,"Comando Qué hace /gohud:preview medieval La hoja de personaje, el zurrón y el diario de misiones en los preajustes medievales /gohud:preview demo --explore hud La demo abierta directamente en un capítulo — hud buttons inputs selection lists data states surfaces prompt touch coach scrolling forms anchors theming /gohud:preview gallery --preset scifi_dark La galería en un preajuste; añade --phone para una ventana de teléfono de 390×844 o --size 1920x1080 para cualquier tamaño /gohud:preview res://ui/main_menu.tscn Una escena de tu propio proyecto, ejecutada dentro de ese proyecto /gohud:preview list Todos los destinos, ids de preajuste y claves de capítulo de la demo /gohud:preview gallery --check Una prueba de humo sin ventana, en modo headless — falla si hay errores de script /gohud:features Todas las funciones, agrupadas, con una línea de código cada una /gohud:features hud Un área en profundidad — surfaces hud style theming icons i18n accessibility config O simplemente pídelo. La skill le enseña al agente toda la API de gohud, así que también funcionan las peticiones en lenguaje natural — \"Crea un menú de pausa con gohud\". Instalada como skill normal en ~/.claude/skills/gohud, los comandos llevan un espacio: /gohud preview demo, /gohud features. Las vistas previas necesitan Godot 4.6 o posterior en tu PATH, o pasar --godot /path/to/godot.","",18],[0,"readable","La legibilidad se mide, no se calcula a ojo",0,"\"Bonito\" es cuestión de gusto; \"legible\" se puede medir. Un texto gris tenue se ve bien en un buen monitor y desaparece en un teléfono a la luz del día — elegir a ojo lo garantiza tarde o temprano. Cada par de colores y la etiqueta de cada estado de botón sobre el panel en el que se apoya se mide contra la WCAG, en los seis temas. Los colores translúcidos se componen primero sobre su fondo real — medirlos directamente da una relación mejor que la que muestra la pantalla. Por eso los colores de texto se derivan, no se eligen: el generador toma la entrada de la paleta como punto de partida y empuja su luminosidad hasta superar el umbral en toda superficie sobre la que pueda caer. Cambia la paleta y el contraste la sigue. Las reglas y las trampas que hay detrás →","python3 addons/gohud/tools/check_contrast.py",-1],[0,"develop","Verificaciones, versiones y este sitio",0,"Un único punto de entrada ejecuta todas las verificaciones; cada parte ve algo que las demás no pueden ver. Verificación Qué detecta run_tests.sh en cuatro tamaños de pantalla Comportamiento y disposición de los widgets, posiciones en RTL, foco de teclado, contraste del skin en ejecución, todos los preajustes new_project_check.sh Dependencias ocultas del proyecto anfitrión; con --zip la versión tal como se distribuye, con --export una compilación Web check_contrast.py Contraste WCAG de cada archivo de tema, estados de botón y paneles translúcidos incluidos check_generated.py · check_scaffold.sh Los temas generados coinciden con sus paletas; un tema desechable se genera y supera el contraste check_package.py Subidas de versión, movimientos del registro de cambios y contenido del ZIP, en copias temporales check_site.py Los enlaces, anclas, idioma de página, glosario y tablas de dials de este sitio Última ejecución registrada — 2026-09-13, Godot 4.7.2, macOS, renderizador Compatibility. 438 de 438 verificaciones a 390×844, 844×390, 768×1024 y 1280×800 en un proyecto vacío; otra vez 438 de 438 con el autoload GoRuntime; una exportación Web; cero fallos de contraste en los seis temas. Godot 4.6 y los dispositivos físicos Android o iOS no formaron parte de esta ejecución.","bash addons/gohud/tools/check_all.sh",-1],[0,"release-versions","Publicar versiones",1,"Una ejecución correcta actualiza plugin.cfg, GoUi.VERSION y CHANGELOG.md a la vez, y mueve las notas de Unreleased a una entrada con fecha. Una ejecución fallida no cambia nada, y un ZIP existente nunca se sobrescribe. El ZIP deja fuera este sitio web, las pruebas y las herramientas.","bash addons/gohud/tools/package.sh # 1.0.1 → 1.0.2 · builds/1.0.2/gohud-1.0.2.zip bash addons/gohud/tools/package.sh --increase-minor-version # 1.0.1 → 1.1.0",24],[0,"this-site","Este sitio",1,"Las páginas son HTML plano en www/ — el inglés en la raíz, el coreano en ko/. Un flujo de trabajo de GitHub Actions publica esa carpeta como raíz del sitio.","python3 addons/gohud/tools/make_site.py # glosario y tablas de dials del skin, generados desde el código python3 addons/gohud/tools/check_site.py # enlaces, anclas, idioma, glosario, tablas generadas bash addons/gohud/tools/site_shots.sh /tmp/shots # capturas de escritorio y de teléfono de cada página",24],[1,"layers","Tres capas",0,"Un preajuste agrupa las tres. Los campos que dejes vacíos recurren a los valores predeterminados. Capa Decide Cómo se cambia Theme Colores, tamaños, escala de texto y la forma de todo lo que dibuja el motor — paneles de botón, campos de entrada, pestañas, gráficos de los interruptores Escribe un .tres, o genera uno con tools/make_theme.py GoSkin La forma de todo lo que dibuja el código — el joystick, las caras de las ranuras rápidas, el anillo de la marca guía, los chips, los esqueletos, los separadores, los encabezados de sección Créale una subclase y sobrescribe solo los métodos que te importen GoIconSet Iconos por nombre — 84 dibujos predeterminados, o los 16 dibujos grabados del juego medieval por encima de ellos. Un paquete de texturas o una fuente de iconos; el código que los llama es idéntico en ambos casos Proporciona un juego completo, o sobrescribe solo unos pocos nombres Por qué un Theme por sí solo no basta. Redondeada es la única esquina que tiene StyleBoxFlat — pon el radio a cero y obtienes un ángulo recto; no hay nada intermedio. Esquinas cortadas en diagonal, un único borde engrosado, un resplandor exterior: el motor no dibuja ninguno de ellos. Y el joystick y la marca guía se dibujan en _draw(), donde un tema no llega en absoluto.","",-1],[1,"pick","Cómo elegir uno",0,"Esa única línea cambia el tema, el skin y los iconos. Desde el editor, usa Ajustes del proyecto → Gohud → Theme → Preset; desde un recurso de configuración, GoConfig.preset.","GoUi.use_preset(GoThemePresets.SCIFI_DARK)",-1],[1,"keeping-one-field-your-own","Cómo conservar un campo propio",1,"Asignar theme, skin o icons de forma explícita tiene prioridad sobre el preajuste.","GoUi.use_preset(GoThemePresets.SCIFI_DARK) GoUi.config.icons = my_icons # tus iconos, y del preajuste todo lo demás",28],[1,"the-six-built-in-presets","Los seis preajustes incluidos",1,"Preajuste Paneles Skin · iconos default_dark · default_light Paneles StyleBoxFlat redondeados sobre una escala graduada de sombras; los botones primarios se elevan y se hunden al pulsarlos GoSkin · 84 iconos predeterminados scifi_dark · scifi_light Paneles GoStyleBoxCut achaflanados con borde de neón y resplandor; marcas de foco GoStyleBoxBracket GoSkinSciFi — joystick hexagonal · iconos predeterminados medieval_dark · medieval_light Marcos GoStyleBoxMedieval forjados — hierro y cuero, o pergamino — con remaches y ornamentos de esquina en los menús GoSkinMedieval · 16 iconos grabados por encima de los predeterminados","",28],[1,"medieval","Medieval: hierro, cuero y pergamino",0,"medieval_dark combina hierro y cuero oscuros con oro antiguo. medieval_light usa pergamino y tinta. Ambos usan GoSkinMedieval, los widgets existentes y 16 iconos originales con detalles de grabado; los iconos de navegación recurren al juego original. Elige el preajuste antes de crear tu interfaz. Las sobrescrituras explícitas de GoConfig.theme, skin o icons siguen teniendo prioridad. Abre res://addons/gohud/examples/medieval/medieval.tscn y pulsa F6 para ver una hoja de personaje, un zurrón y un diario de misiones en funcionamiento. Sus botones alternan las variantes y abren el detalle de los objetos. Hierro y cuero Pergamino y tinta Los marcos de menú llevan un remache y un pequeño ornamento de esquina; el HUD siempre visible mantiene un borde discreto. La vida, el maná y la resistencia usan rellenos rojo, azul y oliva. Cinzel se limita a títulos y subtítulos; el texto del cuerpo conserva la fuente del proyecto anfitrión o la predeterminada. La fuente incluida trae su licencia en assets/fonts/cinzel/OFL.txt. El juego grabado redibuja bag, book, box, coin, crown, flag, heart, key, map, potion, shield, star, sword y user, y añade scroll y seal. Cualquier otro nombre recurre al juego predeterminado, así que close y settings conservan sus dibujos predeterminados en todos los preajustes. Cinzel cubre el alfabeto latino; dale a los encabezados localizados una fuente propia a través de shape.fonts. Qué verifica la batería de pruebas en ambas variantes. Que el skin medieval queda seleccionado; que los paneles de menú y de HUD son marcos forjados, con el ornamento solo en los menús; que los títulos usan Cinzel mientras el texto del cuerpo conserva la fuente heredada; que los iconos grabados se importan como DPITexture; que una ranura rápida real usa el skin; que cambiar los dials de un skin copiado llega a la ranura sin tocar el preajuste; y que al volver atrás se restaura la geometría predeterminada y la de ciencia ficción.","GoUi.use_preset(GoThemePresets.MEDIEVAL_DARK) # O bien: GoUi.use_preset(GoThemePresets.MEDIEVAL_LIGHT)",-1],[1,"make-a-kingdom-of-your-own","Crea un reino propio",1,"Los temas JSON pueden heredar de otros temas JSON. Los valores omitidos conservan los del padre; la herencia circular se rechaza. El preajuste generado conserva el juego de iconos de su padre. Ajuste Efecto shape.material 0: hierro · 1: cuero · 2: pergamino. Controla las marcas de la superficie. shape.grain_alpha Opacidad de la textura. Usa 0 para una superficie limpia. shape.ornament_scale · shape.bevel_strength Tamaño del ornamento de esquina del menú e intensidad del realce biselado. shape.fonts Asigna los roles de título, subtítulo, leyenda, cuerpo y botón a archivos de fuente res:// locales del add-on. Los roles omitidos conservan su fuente heredada. skin.dials Radio de las ranuras rápidas, visibilidad de los remaches, grano y realce. La tabla completa de más abajo enumera cada dial.","python3 addons/gohud/tools/new_theme.py kingdom --from medieval_dark # Edita themes/palettes/kingdom.json y luego: python3 addons/gohud/tools/make_theme.py kingdom godot --headless --path . --import # En GDScript, antes de crear los widgets: GoUi.use_preset(&\"kingdom\")",31],[1,"tokens","Tokens",0,"Cada color y cada medida viven bajo el tipo GoHud dentro del Theme, y se direccionan por nombre. La regla es no escribir números: los nombres acompañan al tema cuando se cambia.","GoUi.color(GoTheme.ACCENT) # color GoUi.metric(GoTheme.GAP) # medida (dp) GoUi.font_size(GoTheme.ROLE_CAPTION) # tamaño para un rol de texto GoUi.box(GoTheme.BOX_CARD) # una copia de un StyleBox",-1],[1,"colours","Colores",1,"Nombre Se usa para background El fondo de la pantalla surface · surface_soft · surface_high Tres capas de panel — panel, tarjeta, celda elevada border Bordes de tarjetas y botones text · secondary · muted Tres niveles de texto — cuerpo, apoyo, atenuado accent · on_accent El acento y el texto que se coloca sobre él success · warning · danger · info Colores de estado para texto *_fill Los mismos estados como relleno — barras y otras áreas grandes scrim · shadow · track El velo detrás de los emergentes, las sombras, el carril de la barra Por qué existe *_fill. El mismo significado, requisitos opuestos. warning usado como texto debe ser lo bastante oscuro para leerse sobre un fondo claro; usado como relleno de una barra de experiencia debe ser lo bastante brillante para notarse. Un solo token no puede ser ambas cosas — la barra del tema claro salía marrón. Un tema sin la variante _fill recurre automáticamente al nombre base, así que los temas anteriores a estos tokens siguen funcionando.","",33],[1,"measurements-dp","Medidas (dp)",1,"touch button_height gap_tiny gap_small gap gap_large padding padding_compact compact_padding_x compact_padding_y radius_small radius radius_large screen_margin scroll_deadzone scroll_edge scrollbar_width list_glyph icon_size notice_duration_ms","",33],[1,"text-roles","Roles de texto",1,"micro · compact · caption · body · button · subtitle · title — un rol nombra un tamaño, no un propósito. \"El texto más grande\", no \"el encabezado\". Así la escala se mantiene aunque una pantalla lo use para otra cosa.","",33],[1,"type-variations","Variaciones de tipo",1,"GoPanel GoCard GoButton GoPrimaryButton GoDangerButton GoDangerSolidButton GoBareButton GoCompactButton GoIconButton GoListButton GoTitleLabel GoSubtitleLabel GoCaptionLabel GoCompactLabel GoMicroLabel","",33],[1,"skin","Skins — allí donde un Theme no llega",0,"Método Decide surface_box · floating_box · overlay_box Las caras de tarjetas y paneles, las superficies flotantes, las píldoras superpuestas sobre el juego o un mapa chip_box · chip_ink El panel de un chip y el color de etiqueta que sigue siendo legible sobre él slot_box · slot_ink Las caras de las ranuras rápidas y su texto disc_box El círculo detrás de un avatar o una insignia alert_box · skeleton_box · segment_box Alertas en línea, marcadores de posición, controles segmentados coach_ring_box La marca que un recorrido guiado dibuja alrededor de su objetivo draw_joystick · draw_coach_pointer Las cosas dibujadas directamente — el joystick y su puntero divider_color · divider_thickness · section_box Separadores y encabezados de sección badge_box Insignias de ranura rápida — cantidad y tiempo restante progress_fill_box · notice_box · tint_notice Rellenos de barra (con contorno cuando un relleno no alcanza 3:1 sobre su carril) y snackbars","class_name MySkin extends GoSkin func draw_joystick(canvas: CanvasItem, center: Vector2, knob: Vector2, radius: float, knob_radius: float, ink: Color, base: Color, active: bool) -> void: # El widget ya ha calculado las posiciones — aquí solo se dibuja canvas.draw_circle(center, radius, Color(base, 0.4)) canvas.draw_circle(knob, knob_radius, ink)",-1],[1,"shapes-styleboxflat-cannot-make","Formas que StyleBoxFlat no puede crear",1,"Clase Qué dibuja GoStyleBoxCut Esquinas cortadas en diagonal, un borde de acento engrosado, un resplandor exterior GoStyleBoxBracket Solo marcas en las esquinas, dejando el contenido sin encerrar GoStyleBoxMedieval Un marco forjado — remaches, grabado en las esquinas, un realce biselado y grano de hierro, cuero o pergamino Las tres se serializan dentro de un recurso Theme como cualquier otro StyleBox — y eso es lo que permite que un tema cambie la forma. Define el relleno mediante content_margin_*. Crear una subclase de StyleBox en GDScript implica que _get_style_margin() nunca se llama (comprobado en Godot 4.7). Rellena los campos integrados o el contenido quedará pegado al borde.","",38],[1,"own","Tu propio preajuste — un solo archivo",0,"Añadir un tema solía significar editar cuatro lugares a mano — la paleta del generador, la forma, un skin, un recurso de preajuste. Ahora un solo comando los deja todos en su sitio. La primera línea escribe themes/palettes/neon.json y themes/presets/neon.tres. El JSON lleva todos los valores del tema del que hereda, detallados por completo, así que sirve además como la lista de lo que puedes cambiar: borra una clave para conservar el valor del padre, escribe una para sobrescribirlo. Los preajustes se localizan recorriendo themes/presets/, así que no hay que cambiar código de registro — el desplegable del ajuste de proyecto también lo detecta.","python3 addons/gohud/tools/new_theme.py neon --from scifi_dark --title \"Neon\" python3 addons/gohud/tools/make_theme.py neon # .tres del tema + gráficos de control godot --headless --path . --import # importa los gráficos nuevos una vez GoUi.use_preset(&\"neon\") # listo — también aparece en el selector",-1],[1,"what-you-can-change-on-one-page","Qué puedes cambiar — en una sola página",1,"Dónde Qué Cómo from el tema padre dark · light · scifi_dark · medieval_dark · … u otro tema JSON. Las claves omitidas heredan sus valores; un ciclo de herencia falla palette fondo · tres superficies · borde · tres tonos de texto · acento · cuatro colores de estado · velo · sombra · carril de la barra \"#RRGGBB\", el alfa como \"#RRGGBB@0.35\" colores vivos solo para relleno *_vivid mantienen las barras saturadas aunque el color del texto tenga que oscurecerse — si omites alguno, el generador lo indica legibilidad no se ajusta a mano. El texto, los bordes, el acento y la etiqueta que va sobre él los empuja el generador hasta que superan los umbrales — cambia solo el acento y las verificaciones siguen pasando shape kind flat (redondeado) · cut (esquinas achaflanadas) · medieval (marcos forjados) tamaños radius · radius_small · radius_large · gap · gap_small · gap_large · padding · button_height · button_padding[4] — los tokens los siguen, así que los paneles y los cálculos de los widgets nunca se contradicen solo cut cut_ratio · cut_max · corners (diagonal|all) · glow · edge solo medieval material (0 hierro · 1 cuero · 2 pergamino) · grain_alpha · ornament_scale · bevel_strength · fonts — title, subtitle, caption, body, button asignados a archivos de fuente res:// locales del add-on skin base — la familia para los sitios donde el código dibuja por su cuenta (joystick, ranuras, insignias, anillo de la marca guía, chips, separadores) default · scifi · medieval dials — los números de esos sitios: ancho y tinte del borde de la ranura, relleno de la insignia, opacidad de chips y alertas, ancho y opacidad del anillo del joystick, tamaños del chaflán de ciencia ficción, resplandor y corchete Cada valor del padre viene detallado en el JSON. El generador los escribe en themes/skins/gohud_skin_<id>.tres — no se toca nada del código del skin. Solo para cambiar los dibujos en sí ejecutas --new-skin, que genera el esqueleto de una subclase de GoSkin icons el juego de iconos una ruta res:// a un recurso GoIconSet — se conserva la del padre JSON cuando se omite dark · title cómo lo muestra el selector booleano · cadena","",40],[1,"every-dial","Todos los dials",1,"La tabla de abajo la rellena tools/make_site.py directamente desde las líneas @export de los scripts de skin — añade un dial o cambia un valor predeterminado y la tabla lo sigue. Usa estos nombres bajo skin.dials en el JSON. Un dial cuyo valor predeterminado se lee 14 es un entero, y uno que se lee 10.0 es un flotante — escribe cualquiera de las dos formas en el JSON y el generador lo convierte al tipo del script. Skin predeterminado GoSkin — 17 Dial Predeterminado Qué define chip_fill_alpha 0.16 Opacidad del relleno del panel de un chip. chip_edge_alpha 0.45 Opacidad del borde del panel de un chip. alert_tint 0.1 Cuánto se tiñe el panel de una caja de alerta hacia su color de estado. slot_tint_lit 0.24 Tinte de acento del panel de una ranura rápida mientras corre su enfriamiento. slot_tint_idle 0.08 Tinte de acento del panel de una ranura rápida en reposo. slot_border_lit 2 Ancho del borde (dp) de una ranura rápida mientras corre su enfriamiento. slot_border_idle 1 Ancho del borde (dp) de una ranura rápida en reposo. badge_pad_x 5 Relleno interior horizontal (dp) de una insignia (cantidad, tiempo restante). badge_pad_y 1 Relleno interior vertical (dp) de una insignia. badge_edge_alpha 0.6 Opacidad del borde del panel de una insignia. float_shadow_alpha 0.45 Opacidad de la sombra de las tarjetas flotantes (marca guía, tarjeta de pregunta). float_shadow_size 14 Desenfoque (dp) de la sombra de las tarjetas flotantes. float_shadow_lift 4 Desplazamiento hacia abajo (dp) de la sombra de una tarjeta flotante. float_glow_size 10.0 Distancia del resplandor (dp) de un panel flotante que resplandece en vez de proyectar sombra, como el panel achaflanado de ciencia ficción. joystick_base_alpha 0.42 Opacidad del disco base del joystick. joystick_ring_alpha 0.45 Opacidad del anillo del joystick. joystick_ring_width 2.0 Ancho (dp) del anillo del joystick. Skin de ciencia ficción GoSkinSciFi — 10 Dial Predeterminado Qué define cut_chip 7.0 Tamaño del chaflán (dp) del panel de un chip. cut_skeleton 5.0 Tamaño del chaflán (dp) de un panel de esqueleto. cut_alert 8.0 Tamaño del chaflán (dp) de una caja de alerta. cut_segment 8.0 Tamaño del chaflán (dp) de un control segmentado. cut_slot 6.0 Tamaño del chaflán (dp) del panel de una ranura rápida. cut_disc_ratio 0.24 El chaflán de avatares y discos = diámetro × esta proporción. slot_glow_alpha 0.45 Opacidad del resplandor de una ranura cuyo enfriamiento está corriendo. slot_glow_size 6.0 Distancia del resplandor (dp) de una ranura cuyo enfriamiento está corriendo. bracket_arm 12.0 Longitud del brazo (dp) del corchete de puntería de la marca guía. bracket_thickness 2.0 Grosor de línea (dp) del corchete de puntería de la marca guía. Skin medieval GoSkinMedieval — 5 Dial Predeterminado Qué define slot_radius 4.0 Radio de esquina (dp) del marco de la ranura rápida medieval. leather_grain_alpha 0.035 Opacidad de las marcas sutiles de cuero dentro de las ranuras rápidas. ornament_scale 1.0 Escala de las decoraciones metálicas en las esquinas de las ranuras rápidas. Los marcos de menú usan shape.ornament_scale. bevel_strength 0.18 Intensidad del realce metálico a lo largo de los bordes de las ranuras rápidas. slot_rivets 1 Mostrar pequeños remaches metálicos en las ranuras rápidas: 0 los oculta, 1 los muestra.","",40],[1,"subclass-the-skin-optional","Crear una subclase del skin (opcional)",1,"En un skin vive únicamente lo que el tema y la forma no alcanzan — el hexágono del joystick, las insignias de las ranuras, el corchete de puntería de la marca guía. Crea una subclase de GoSkin, sobrescribe solo esos métodos y apunta el campo skin del JSON a ese recurso. Un tema que solo cambia colores se salta este paso. Una verificación mantiene la promesa. tools/check_scaffold.sh crea un tema desechable en cada ejecución — cambia el acento, pone el radio en 4 — y comprueba la generación, la propagación de tokens y un contraste limpio antes de eliminarlo. La primera ejecución encontró un tema con solo el acento cambiado que fallaba en 8 pares: el generador empujaba los colores de texto pero usaba el acento tal cual. Ahora también empuja el acento y la etiqueta que va sobre él.","",40],[1,"contrast","La legibilidad se mide",0,"\"Bonito\" es cuestión de gusto; \"legible\" se puede medir. Un texto gris tenue se ve bien en un buen monitor y desaparece en un teléfono a la luz del día — elegir a ojo lo garantiza tarde o temprano. Qué Exigido Texto del cuerpo 4.5 : 1 Texto grande (24px en adelante) 3 : 1 Bordes de acento e iconos 3 : 1 Bordes decorativos 2 : 1 — la WCAG no aplica su regla de 3:1 a la decoración Superficies adyacentes 1.12 : 1 — lo justo para que una tarjeta se distinga de su fondo","python3 addons/gohud/tools/check_contrast.py",-1],[1,"same-hue-text-on-a-same-hue-tint","Texto de un tono sobre un tinte del mismo tono",1,"Esta trampa apareció tres veces en este código — botones pulsados (panel de acento, etiqueta de acento), botones de peligro y chips. Se ve bien en una muestra de color y se derrumba en cuanto se mide, porque ambos comparten el tono y por tanto no tienen diferencia de luminosidad. Por eso los colores de etiqueta no se eligen a mano. El generador de temas y GoSkin empujan cada uno la luminosidad — y solo la luminosidad — hasta superar el umbral sobre el panel en el que el texto realmente se apoya. El tono y la saturación sobreviven, así que la paleta conserva su carácter y, al cambiarla, conserva su contraste.","",44],[1,"colour-read-as-text-and-colour-painted-as-area-w","El color leído como texto y el color pintado como área quieren cosas opuestas",1,"En un tema claro, un color de advertencia debe oscurecerse para seguir siendo legible como texto (#96500A). Cuando el relleno de la barra hereda ese color, la barra de experiencia se vuelve marrón. El color por sí solo no lo arregla: el amarillo es intrínsecamente brillante, así que supera el 3:1 sobre un carril gris cualquiera, y oscurecer el carril lo empeora (1.52 → 1.06). Por eso los dos se separan. El color se mantiene vivo — la paleta lleva colores solo para relleno como warning_vivid. El borde es el que aporta el contraste — GoSkin dibuja un contorno de 1dp sobre cualquier relleno que no alcance 3:1 contra su carril, para que \"cuánto queda\" siga siendo legible. Si lo omites, se te avisa. Sin un *_vivid, un relleno que sale oscuro hace que el generador imprima 막대가 칙칙하다 — 팔레트에 warning_vivid 를 더한다 (en coreano: \"la barra se ve apagada — añade warning_vivid a la paleta\"). Un punto que antes se degradaba en silencio ahora lo dice.","MY_LIGHT = dict( warning=hexc(\"9A5407\"), # leído como texto warning_vivid=hexc(\"F2A007\"), # pintado en la barra )",44],[1,"a-floating-panel-cannot-know-what-is-behind-it","Un panel flotante no puede saber qué hay detrás",1,"Un HUD se dibuja sobre el juego — un campo nevado, o una cueva. Si su panel es translúcido, lo que haya detrás se filtra y cambia el color del panel, arrastrando el contraste del texto con él. Al 82% de opacidad, el texto atenuado de los temas oscuros caía a 3.74:1 sobre un fondo brillante — por debajo del mínimo. Por eso los paneles translúcidos se miden con blanco puro y negro puro detrás; eso es lo peor que puede ofrecer una escena de juego. El panel de HUD de los temas incluidos es lo bastante opaco para pasar (92%) sin perder el aspecto vidrioso. Por la misma razón, los colores de los iconos tampoco son fijos. El glifo de la ranura rápida estaba escrito a fuego en blanco y medía 1.11:1 en un tema claro — ahora sigue al panel sobre el que se apoya, exactamente igual que las etiquetas. Dos verificadores, dos alcances. check_contrast.py lee los archivos de tema; los colores que un skin mezcla en tiempo de ejecución (chips, ranuras) los mide la sección skin contrast de la batería de pruebas dentro de Godot.","",44],[2,"surfaces","Ventanas flotantes",0,"","",-1],[2,"gosurface-the-shell","GoSurface — el contenedor",1,"Los emergentes, las hojas y los desplegables usan todos este. Se encarga del área segura, el teclado virtual, el encabezado y el pie fijos, el cuerpo desplazable, qué ventana está encima, la restauración del foco, la propiedad del botón Atrás y el redimensionado por arrastre. Colocación Se ve como Se usa para CENTER Una tarjeta en el medio Confirmaciones, ajustes BOTTOM Una hoja que sube desde abajo Listas, páginas de gestión ANCHOR Una tarjeta fijada junto a un control Desplegables, menús contextuales No se elimina a sí mismo. Reaccionar a close_requested — ocultarlo o liberarlo — es tarea de la pantalla que lo posee, porque el contenedor no puede saber por qué se está cerrando (guardar y cerrar, o descartar).","",48],[2,"gosheet-a-page-from-the-bottom","GoSheet — una página desde abajo",1,"Posee un CanvasLayer, así que queda de forma fiable por encima del HUD. open() vacía el cuerpo y desactiva el botón Atrás y las filas fijas — un botón muerto en una pantalla a la que no hay adónde volver se lee como algo roto.","var sheet := GoSheet.new() add_child(sheet) sheet.open(\"Inventario\") sheet.toolbar().add_child(GoStyle.line_edit(\"Buscar…\")) sheet.toolbar().visible = true sheet.footer().add_child(GoStyle.button(\"Cerrar\", sheet.close, GoStyle.Tone.PRIMARY)) sheet.footer().visible = true",48],[2,"godialogs-confirmations-you-await","GoDialogs — confirmaciones con await",1,"confirm(title, body, ok_text, cancel_text, extra, args, destructive) — todo lo que va después del cuerpo es opcional, y alert() funciona igual pero con un solo botón. Activa destructive para algo que no se puede deshacer: el botón de confirmar pasa a ser el botón relleno GoStyle.Tone.DANGER_SOLID. En un tema claro, una etiqueta de peligro teñida tiene que oscurecerse hasta leerse como texto negro; el botón relleno mantiene texto blanco sobre rojo. El tono se vuelve a aplicar en cada llamada porque se reutiliza una sola ventana, y un segundo confirm() mientras hay uno abierto devuelve false de inmediato. confirm_key() acepta claves de traducción. Disposición de los botones. action_layout es VERTICAL por omisión (seguro para traducciones largas), HORIZONTAL para una sola fila con la mitad del ancho cada uno, o AUTO, que usa una fila solo cuando ambas etiquetas caben en la mitad de la tarjeta en una sola línea y las apila en caso contrario. action_gap es el espacio entre los botones y body_gap el espacio por encima de ellos — hazlo más ancho que el hueco entre botones para que la pregunta y la elección se lean como dos partes. Para un único diálogo, llama a set_next_action_layout() antes de abrirlo. La fila se construye cuando un diálogo se abre por primera vez, así que un GoDialogs en autoload no añade nada al arranque.","if await dialogs.confirm(\"Borrar partida\", \"Esto no se puede deshacer.\"): delete_save()",48],[2,"goform-a-width-capped-form","GoForm — un formulario de ancho limitado",1,"Garantiza que las etiquetas descendientes se ajusten por líneas. Sin eso, una frase larga se estira en una sola línea cuyo ancho mínimo supera el de la pantalla, y los lados quedan recortados — ni siquiera puedes saber en qué pantalla estás. Activar el ajuste a mano en cada escena se olvida siempre.","",48],[2,"goscroll-touch-scrolling","GoScroll — desplazamiento táctil",1,"Mete una sola cosa dentro. Los encabezados y las filas de botones van fuera — una lista larga no debe empujarlos fuera de la pantalla. use_panel_edge() mueve la barra de desplazamiento al relleno que la tarjeta ya tiene mientras el contenido mantiene su sangría.","",48],[2,"messages","Decirle algo al jugador",0,"","",-1],[2,"gonotice-snackbar","GoNotice — snackbar",1,"Nunca intercepta la entrada. Un aviso se lee, no se pulsa. No toma el foco, no bloquea la entrada del juego, y el botón que hay debajo sigue pulsándose. Cuando hace falta una confirmación usa GoDialogs; cuando hace falta elegir, GoPromptCard.","",54],[2,"gopromptcard-a-question-that-does-not-block","GoPromptCard — una pregunta que no bloquea",1,"Flota a un lado sin velo de fondo. El juego sigue corriendo.","",54],[2,"gocoachmark-guided-tour","GoCoachMark — recorrido guiado",1,"Señala controles reales de uno en uno. Solo la tarjeta toma la entrada, así que pulsar el propio control resaltado hace avanzar el recorrido — \"pulsa aquí\" se convierte en una acción en vez de en una frase. title y body pueden ser claves de traducción o texto plano. Un paso cuyo objetivo ha desaparecido se omite.","tour.start([ {\"target\": bag_button, \"title\": \"Bolsa\", \"body\": \"Todo lo que recoges acaba aquí.\"}, {\"target\": map_button, \"title\": \"Mapa\", \"body\": \"Pulsa para abrir el mapa completo.\"}, ])",54],[2,"hud","HUD",0,"","",-1],[2,"the-small-things-decide-whether-it-looks-good","Los detalles pequeños deciden si se ve bien",1,"Pule los paneles grandes cuanto quieras — lo que llama la atención siempre es algo pequeño: una palabra partida en dos, un resplandor cortado, una ranura apretada. El 2026-09-13 se señalaron cuatro cosas así y se corrigieron en los widgets y los temas, no en la pantalla de la demo, para que todas las pantallas obtengan el mismo resultado. Qué se veía Causa Solución El Done de la marca guía se convertía en Don/e Un botón con el ajuste de línea activado resta el ancho de su texto de su mínimo — apriétalo y se parte dentro de una palabra GoStyle.fit_words(): una sola palabra nunca se parte; varias palabras se ajustan por líneas, pero la palabra más larga siempre cabe — se juzga sobre el texto mostrado, no sobre la clave de traducción, y el formulario lo vuelve a aplicar cuando cambia el idioma El resplandor de un botón a todo lo ancho quedaba cortado en vertical por la izquierda Un contenedor de desplazamiento recorta en su borde, sin excepciones. Solo sobrevivía el lado derecho, gracias al canal de la barra GoScroll toma prestado el relleno del padre para empujar su borde 12dp hacia fuera y lo devuelve por dentro — el contenido no se mueve El tiempo, el icono y la cantidad se apilaban en vertical dentro de una ranura Tres filas dentro de 48dp Icono grande en el centro, atajo arriba a la izquierda, cantidad como insignia abajo a la derecha, tiempo restante como insignia sobre el icono — los paneles de insignia vienen del badge_box() del skin Un desplegable plano sin selección visible El resaltado de los elementos usaba el panel de botón; las marcas de radio eran las tenues predeterminadas del motor Un panel de resaltado propio (tinte de acento suave), el mismo gráfico de radio que las casillas, y altura de elemento dimensionada para el tacto Desplegable — panel de resaltado y marca de radio Ranuras — insignias de esquina y tiempo restante (ciencia ficción) Dale a los botones de solo icono una descripción con GoStyle.icon_button(icon, action, -1, tooltip_key) — el tooltip para quien usa ratón y el nombre accesible para los lectores de pantalla salen ambos de ese único valor. gohud dibuja el tooltip por su cuenta: el del motor parte el texto a un carácter por línea cuando su cálculo de ancho falla (medido a 1dp de ancho). La tarjeta de la marca guía se aparta de los elementos fijos En horizontal, la tarjeta se enviaba antes al borde superior o inferior — justo donde viven los encabezados y las piezas del HUD; en la demo se posaba sobre el → × del encabezado. Ahora se mantiene al nivel de su objetivo, rodea cualquier GoHudAnchor que reserve espacio, y admite otros elementos a esquivar mediante keep_clear. Se mueve la distancia más corta que libra el obstáculo sin tapar el objetivo, y se queda donde está cuando la pantalla es demasiado pequeña para librarlo todo — solaparse es mejor que desaparecer. Su profundidad — para que se lea como algo por encima de la página — viene de los dials del skin (float_shadow_size, float_shadow_lift, float_shadow_alpha; los skins achaflanados usan float_glow_size).","tour.keep_clear = [header_bar, toolbar] # elementos fijos que no son anclas",58],[2,"screens-with-a-mouse-and-a-keyboard","Pantallas con ratón y teclado",1,"Un dedo no tiene estado de hover. Si desarrollas solo pensando en móvil, dos estados exclusivos de escritorio quedan sin verificar — y uno de ellos estaba roto: el anillo de foco de gohud era invisible sobre un botón primario. El panel es del color de acento y el anillo también lo era: 1.00:1, el mismo color dibujado sobre sí mismo. Al moverte con el teclado, no había forma de saber dónde estabas. De arriba abajo: normal · hover · foco. Los botones rellenos reciben un anillo que contrasta con su panel. Los botones rellenos (GoPrimaryButton, GoDangerSolidButton) usan un anillo que contrasta con su propio panel — oscuro en un tema oscuro, blanco en uno claro, un corchete de puntería oscuro en ciencia ficción. El verificador de contraste mide el anillo de foco contra el panel en el que se apoya, así que la regla sobrevive a un cambio de paleta (la WCAG 2.4.11 pide 3:1 en los indicadores de foco).","",58],[2,"gohudanchor-nine-spots","GoHudAnchor — nueve puntos",1,"Respeta el área segura y los márgenes de borde. Dale un landscape_spot y se moverá en horizontal — los controles que en vertical van abajo al centro pueden pasar abajo a la derecha. Por qué existe. Escritos a mano pieza por pieza, los anclajes y los desplazamientos se desajustan: una barra de vida acaba debajo del recorte de la cámara en un dispositivo con muesca, y un botón de control cae sobre la barra de gestos en horizontal. Esa aritmética vive en un único lugar. Mantener el contenido fuera de debajo del HUD Cuando una pantalla desplazable comparte la vista con un HUD, el contenido se desliza por debajo de él y los dos conjuntos de texto se solapan hasta que no se puede leer ninguno. Pasó dos veces en este add-on: el texto de sugerencia de un campo se colaba entre las ranuras rápidas, y el mando de un interruptor de ajustes caía sobre la barra de vida. Cada rectángulo se esquiva en la dirección que menos área cuesta. Una barra arriba a la derecha se rodea hacia abajo en un teléfono vertical (13% de la altura) y hacia los lados en horizontal (21% del ancho) — esquivarla en vertical estando en horizontal costaría el 27% de la pantalla. El terreno ya cedido se resta antes de medir el siguiente rectángulo. Las piezas del HUD también chocan entre sí Los nueve puntos reparten la pantalla; no garantizan que las piezas no se toquen. Un snackbar ancho arriba al centro caía justo encima de la barra de vida de arriba a la derecha, ocultando el valor — no se podía leer cuánta vida quedaba. Se aparta solo en vertical — moverse también hacia los lados haría que un aviso centrado apareciera en un sitio distinto cada vez. Y solo esquiva las piezas que no se están apartando ellas mismas: si ambas ceden, las dos se intercambian el sitio eternamente.","form.avoid_hud = true # se aparta de todo GoHudAnchor visible joystick_anchor.reserve_space = false # …salvo los que solo aparecen bajo un dedo notice_anchor.avoid_peers = true # se coloca debajo del HUD fijo notice_anchor.reserve_space = false # y no empuja la página mientras está visible",58],[2,"gobar-health-mana-experience","GoBar — vida, maná, experiencia",1,"Los cambios se suavizan durante 0,18 s — una barra de vida que salta no te dice con cuánta fuerza te han golpeado. reduce_motion lo hace instantáneo. Los números grandes se abrevian a 12.3k para que el ancho de la barra no tiemble según entran y salen dígitos.","var hp := GoBar.new() hp.label_text = \"HP\" hp.ink = GoUi.color(GoTheme.DANGER_FILL) # el token solo de relleno hp.set_values(320, 500) # \"320 / 500\"",58],[2,"goslot-one-quick-slot","GoSlot — una ranura rápida",1,"Icono, cantidad, enfriamiento y atajo en una sola cara. Colgar insignias de un círculo pequeño hace que cada ranura tenga un ancho distinto y la fila se tambalee. El tamaño visible y el tamaño táctil son distintos. Las ranuras apretadas tienen cajas táctiles de 48dp que se solapan; el solape va a la ranura cuyo centro esté más cerca — háblales unas de otras mediante touch_peers. keyboard_focus está desactivado por omisión, para que una fila de ocho ranuras no se interponga entre quien usa teclado y todos los controles de ajustes en el orden de tabulación. Actívalo cuando el teclado o el mando sean la única entrada.","",58],[2,"gojoystick-virtual-stick","GoJoystick — stick virtual",1,"Modo Comportamiento FIXED Siempre en el mismo sitio — fácil de encontrar sin mirar FOLLOW Aparece donde cae el pulgar RELATIVE Sigue al pulgar después de aparecer — cómodo para desplazamientos largos El Vector2 de moved tiene una longitud de 0 a 1, así que puedes multiplicarlo directamente por una velocidad; no varía con el tamaño de pantalla ni con el DPI.","",58],[2,"goiconbutton-looks-small-presses-large","GoIconButton — se ve pequeño, se pulsa grande",1,"Solo es seguro mientras sus hermanos ignoren la entrada. Si el área ampliada cubre el botón siguiente, ese botón deja de responder. Los botones de icono uno al lado del otro necesitan touch_peers.","",58],[2,"factory","GoStyle — un solo lugar donde se crean las cosas",0,"Llama a Button.new() directamente y el relleno, la altura y el ajuste de línea se desvían ligeramente de una pantalla a otra. Esa desviación es invisible en una revisión de código y evidente en una captura. Grupo Funciones Estructura column row wrap_row padding spacer divider responsive_grid aspect foldable Texto label label_key line section typography Botones button button_key icon_button list_button list_row apply_icon style_choice_card style_chip_button style_chip_label Entrada line_edit textarea toggle checkbox slider picker select dropdown radio_group segmented choice_grid Presentación card chip hud_panel chip_panel avatar skeleton alert table tabs breadcrumb progress empty_state Piezas de superficie surface box floating disc face_padding Utilidades form fit_words natural_width tooltip_node card_body let_input_through box() siempre devuelve un StyleBoxFlat, porque quien lo llama lo recibe y ajusta bg_color o corner_radius. Usa surface() cuando una forma personalizada deba sobrevivir.","",-1],[2,"list-rows-with-a-description","Filas de lista con descripción",1,"Una fila con segunda línea recibe el mismo relleno arriba y abajo, más holgado que una fila de una sola línea, y el par título/descripción se mantiene centrado en vertical junto al icono — también cuando un contenedor estira la fila a más altura, y después de que la descripción se reparta en varias líneas. Toda la fila sigue siendo un único objetivo táctil. Filas de dos líneas, ranuras y barras en el ejemplo medieval — las mismas llamadas a la fábrica bajo medieval_light.","GoStyle.list_button(GoIconSet.SWORD, \"Guardajuramentos\", _inspect, Color.TRANSPARENT, \"Espada larga / Ataque 42\", false)",66],[2,"flowing-rows","Filas que fluyen",1,"Mete los controles en wrap_row con su ancho natural. Con el ajuste de línea activado, el ancho mínimo de un botón baja hasta casi nada y la fila dimensiona su celda con ese valor — la etiqueta se reduce a un carácter por línea. La fábrica lo evita por ti.","",66],[2,"never-leave-an-empty-list-empty","Nunca dejes vacía una lista vacía",1,"La gente lee una pantalla en blanco como algo roto.","page.add_child(GoStyle.empty_state(GoIconSet.BOX, \"Aquí todavía no hay nada\"))",66],[2,"hooks","Hooks de subclase",0,"Cada punto en el que se construye un widget hijo pasa por un método sobrescribible, de modo que un proyecto que cree subclases de los tipos de gohud puede meter sus propias subclases dentro de los widgets sin copiar código. Hook Widget Predeterminado _make_scroll() GoCoachMark, GoSurface GoScroll.new() _make_close_button() GoPromptCard, GoSurface GoIconButton.new() _make_surface() GoSheet, GoDialogs GoSurface.new() _should_pause() GoCoachMark Oculta la tarjeta mientras hay un modal abierto","",-1]]};
